async function getAtomDetails(atomId) {
  try {
    const data = await fetcher(
      GetAtomDocument,
      {
        id: atomId
      }
    )();
    if (data?.atom) {
      return data.atom;
    }
    return null;
  } catch (error) {
    console.error("Error fetching atom:", error);
    return null;
  }
}
async function getTripleDetails(id) {
  try {
    const data = await fetcher(
      GetTripleDocument,
      {
        tripleId: id
      }
    )();
    if (data?.triple) {
      return data.triple;
    }
    return null;
  } catch (error) {
    console.error("Error fetching triple:", error);
    return null;
  }
}
