async function createAtomFromEthereumAccount(config, data, depositAmount) {
  if (!isAddress(getAddress(data))) {
    throw new Error("Invalid Ethereum address provided");
  }
  const { address, publicClient } = config;
  const atomBaseCost = await multiVaultGetAtomCost({
    publicClient,
    address
  });
  const uriRef = getAddress(data);
  const assets = atomBaseCost + BigInt(depositAmount || 0);
  const txHash = await multiVaultCreateAtoms(config, {
    args: [[toHex(uriRef)], [assets]],
    value: assets
  });
  if (!txHash) {
    throw new Error("Failed to create atom onchain");
  }
  const events = await eventParseAtomCreated(publicClient, txHash);
  return {
    uri: uriRef,
    transactionHash: txHash,
    state: events[0].args
  };
}

// src/external/upload-json-to-pinata.ts
async function uploadJsonToPinata(apiToken, jsonData) {
  try {
    const res = await fetch("https://api.pinata.cloud/pinning/pinJSONToIPFS", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiToken}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(jsonData)
    });
    if (!res.ok) {
      throw new Error(`Pinata upload failed: ${res.statusText}`);
    }
    return res.json();
  } catch (error) {
    throw new Error(
      `Failed to upload JSON to Pinata: ${error instanceof Error ? error.message : "Unknown error"}`
    );
  }
}

